create or replace function public.platform_workspace_directory() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or not private.is_platform_admin() then raise exception 'forbidden'; end if; return coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('charity_code',c.charity_code)) from public.platform_list_charities() x join public.charities c on c.id=x.id),'[]'::jsonb); end $$; revoke all on function public.platform_workspace_directory() from public,anon; grant execute on function public.platform_workspace_directory() to authenticated;
